const fs = require("node:fs");
const path = require("node:path");
module.exports = async function prepareFonts() {
  const { FONTS } = await import("../src/fonts.mjs");
  const imports = [
    "/* Generated by scripts/prepare-fonts.cjs. Font licenses are in licenses/. */",
  ];
  for (const font of FONTS.filter((f) => f.package)) {
    const folder = path.join(__dirname, "../node_modules", font.package);
    let regular = false;
    for (const style of ["normal", "italic"]) {
      for (const weight of [
        400,
        fs.existsSync(
          path.join(
            folder,
            `latin-600${style === "italic" ? "-italic" : ""}.css`,
          ),
        )
          ? 600
          : 700,
      ]) {
        const file = `latin-${weight}${style === "italic" ? "-italic" : ""}.css`;
        if (!fs.existsSync(path.join(folder, file))) continue;
        imports.push(`@import "${font.package}/${file}";`);
        if (weight === 400 && style === "normal") regular = true;
      }
    }
    if (!regular)
      throw new Error(`A regular face is missing for ${font.family}.`);
  }
  fs.writeFileSync(
    path.join(__dirname, "../src/font-faces.css"),
    imports.join("\n") + "\n",
  );
  console.log(
    `Prepared ${FONTS.filter((f) => f.package).length} bundled font families.`,
  );
};
